import java.awt.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.Base64;
import java.sql.*;
import java.util.Arrays;
import java.util.concurrent.ExecutionException;
import javax.imageio.ImageIO;
import javax.swing.*;
import javax.swing.border.*;
import javax.swing.plaf.basic.BasicButtonUI;

public class LoginFrame extends JFrame {
    private static final Color CANVAS = new Color(0xFBF4F3);
    private static final Color INK = new Color(0x332728);
    private static final Color MUTED = new Color(0x695758);
    private static final Color RED = new Color(0x822D37);
    private static final Color BLUSH = new Color(0xF8DCDD);
    private static final Color LINE = new Color(0xDDC7C7);

    private final JTextField id = new JTextField();
    private final JPasswordField password = new JPasswordField();
    private final JButton submit = new JButton("Sign in");
    private final JLabel message = new JLabel(" ", SwingConstants.CENTER);

    public LoginFrame() {
        super("Digital Library | NIET Greater Noida");
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        JPanel page = new JPanel(new GridBagLayout());
        page.setBackground(CANVAS);
        page.setBorder(new EmptyBorder(20, 20, 20, 20));
        JPanel card = new JPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBackground(Color.WHITE);
        card.setBorder(new CompoundBorder(new LineBorder(LINE), new EmptyBorder(26, 30, 18, 30)));
        ImageIcon logo = loadLogo();
        if (logo != null) {
            JLabel brand = new JLabel(logo);
            brand.getAccessibleContext().setAccessibleName("NIET logo");
            addRow(card, brand, 10);
        }
        addRow(card, label("Digital Library", 28, Font.BOLD, INK), 3);
        addRow(card, label("NIET Greater Noida", 14, Font.PLAIN, MUTED), 24);
        addField(card, "Library ID", id);
        addField(card, "Password", password);

        submit.setUI(new BasicButtonUI());
        submit.setOpaque(true);
        submit.setContentAreaFilled(true);
        submit.setBackground(BLUSH);
        submit.setForeground(RED);
        submit.setFont(new Font("Segoe UI", Font.BOLD, 16));
        submit.setBorder(new LineBorder(new Color(0xC58589)));
        submit.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        sizeRow(submit, 42);
        addRow(card, submit, 8);
        message.setForeground(RED);
        message.setFont(new Font("Segoe UI", Font.PLAIN, 13));
        addRow(card, message, 0);
        page.add(card);
        setContentPane(page);
        getRootPane().setDefaultButton(submit);
        submit.addActionListener(e -> signIn());
        pack();
        setMinimumSize(getSize());
        setLocationRelativeTo(null);
        addWindowListener(new WindowAdapter() {
            public void windowOpened(WindowEvent e) { id.requestFocusInWindow(); }
        });
    }

    private static JLabel label(String text, int size, int style, Color color) {
        JLabel label = new JLabel(text);
        label.setFont(new Font("Segoe UI", style, size));
        label.setForeground(color);
        return label;
    }

    private static void addRow(JPanel card, JComponent item, int gap) {
        item.setAlignmentX(Component.CENTER_ALIGNMENT);
        card.add(item);
        if (gap > 0) card.add(Box.createVerticalStrut(gap));
    }

    private static void sizeRow(JComponent item, int height) {
        Dimension size = new Dimension(325, height);
        item.setPreferredSize(size);
        item.setMaximumSize(size);
    }

    private static void addField(JPanel card, String text, JTextField field) {
        JLabel caption = label(text, 14, Font.BOLD, INK);
        caption.setLabelFor(field);
        sizeRow(caption, 20);
        addRow(card, caption, 5);
        sizeRow(field, 40);
        field.setFont(new Font("Segoe UI", Font.PLAIN, 16));
        field.setForeground(INK);
        field.setBackground(Color.WHITE);
        field.setCaretColor(RED);
        field.setBorder(fieldBorder(LINE));
        field.addFocusListener(new FocusAdapter() {
            public void focusGained(FocusEvent e) { field.setBorder(fieldBorder(RED)); }
            public void focusLost(FocusEvent e) { field.setBorder(fieldBorder(LINE)); }
        });
        addRow(card, field, 15);
    }

    private static Border fieldBorder(Color color) {
        return new CompoundBorder(new LineBorder(color), new EmptyBorder(4, 10, 4, 10));
    }

    private static ImageIcon loadLogo() {
        try {
            byte[] png = Base64.getDecoder().decode(embeddedLogo());
            BufferedImage image = ImageIO.read(new ByteArrayInputStream(png));
            double scale = Math.min(270.0 / image.getWidth(), 125.0 / image.getHeight());
            int width = Math.max(1, (int)Math.round(image.getWidth() * scale));
            int height = Math.max(1, (int)Math.round(image.getHeight() * scale));
            return new ImageIcon(image.getScaledInstance(width, height, Image.SCALE_SMOOTH));
        } catch (IOException ex) {
            return null;
        }
    }

    private void signIn() {
        if (!submit.isEnabled()) return;
        String userId = id.getText().trim();
        char[] secret = password.getPassword();
        if (userId.isEmpty() || secret.length == 0) {
            Arrays.fill(secret, '\0');
            message.setText("Enter your library ID and password.");
            (userId.isEmpty() ? id : password).requestFocusInWindow();
            return;
        }
        submit.setEnabled(false);
        id.setEditable(false);
        password.setEditable(false);
        message.setText("Signing in…");
        new SwingWorker<CurrentUser, Void>() {
            protected CurrentUser doInBackground() throws SQLException {
                try {
                    return authenticate(userId, new String(secret));
                } finally {
                    Arrays.fill(secret, '\0');
                }
            }
            protected void done() {
                submit.setEnabled(true);
                id.setEditable(true);
                password.setEditable(true);
                try {
                    CurrentUser user = get();
                    if (user != null) {
                        DashboardFrame.forUser(user).setVisible(true);
                        dispose();
                    } else {
                        message.setText("Check your library ID and password.");
                        password.selectAll();
                        password.requestFocusInWindow();
                    }
                } catch (ExecutionException ex) {
                    message.setText("Could not sign in. Check the database connection.");
                } catch (InterruptedException ex) {
                    Thread.currentThread().interrupt();
                    message.setText("Sign-in interrupted. Please try again.");
                }
            }
        }.execute();
    }

    private static CurrentUser authenticate(String id, String password) throws SQLException {
        String sql = "SELECT librarian_id, name, 'Librarian' FROM librarians "
                + "WHERE librarian_id = ? AND password = ? UNION ALL "
                + "SELECT member_id, name, 'Member' FROM members WHERE member_id = ? AND password = ?";
        try (Connection connection = DBConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, id);
            statement.setString(2, password);
            statement.setString(3, id);
            statement.setString(4, password);
            try (ResultSet rows = statement.executeQuery()) {
                if (!rows.next()) return null;
                CurrentUser user = new CurrentUser(rows.getString(1), rows.getString(2), rows.getString(3));
                return rows.next() ? null : user;
            }
        }
    }
    // Original NIET PNG, stored in pieces to fit Java class-file string limits.
    private static String embeddedLogo() {
        return String.join("",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "");
    }
}
